const API = window.iothunter?.apiBase || 'http://127.0.0.1:18080';
const requestedLang = new URLSearchParams(location.search).get('lang');
const requestedPage = new URLSearchParams(location.search).get('page');
const state = { page: requestedPage || 'overview', workspaces: [], selected: null, detail: null, registry: {}, history: [], historyIndex: -1, agentSelected: null, deviceSelected: null, conversationSelected: null, taskSelected: null, lang: requestedLang === 'en' || requestedLang === 'zh' ? requestedLang : (localStorage.getItem('iothunter.lang') || 'zh'), search: '' };
const initialLayout = ['overview','tasks'].includes(state.page) ? 'layout-queue-content-inspector' : ['targets','evidence','devices','connections','validation','vulnerabilities','risk'].includes(state.page) ? 'layout-content-inspector' : 'layout-content';
document.querySelector('.workbench')?.classList.add(initialLayout);
