const t = (value) => state.lang === 'zh' ? (translations[value] || value) : value;
function localize() { document.documentElement.lang=state.lang==='zh'?'zh-CN':'en'; document.querySelectorAll('[data-i18n]').forEach((node)=>{ node.textContent=t(node.dataset.i18n); }); document.querySelectorAll('[data-i18n-placeholder]').forEach((node)=>{ node.placeholder=t(node.dataset.i18nPlaceholder); }); const walker=document.createTreeWalker(document.getElementById('content'),NodeFilter.SHOW_TEXT); const nodes=[]; while(walker.nextNode()) nodes.push(walker.currentNode); nodes.forEach((node)=>{ const raw=node.nodeValue.trim(); if(raw && translations[raw]) node.nodeValue=node.nodeValue.replace(raw,t(raw)); }); $('language').textContent=state.lang==='zh'?'EN':'中文'; }
const toast = (message, error = false) => { const el=$('toast'); el.textContent=message; el.className='toast show'+(error?' error':''); clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.className='toast',3200); };
const fmt = (value) => value ? new Date(value).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}) : '-';
const d = () => state.detail || {};
const workspace = () => state.workspaces.find((item)=>item.id===state.selected);
const pill = (value) => { const danger=['failed','rejected','cancelled','dropped'].includes(value); const warn=['queued','running','pending','blocked','paused'].includes(value); return '<span class="pill '+(danger?'danger':warn?'warn':'')+'">'+esc(value||'unknown')+'</span>'; };
const empty = (message) => '<div class="empty">'+message+'</div>';
const card = (title, subtitle, body, action='') => '<section class="card"><div class="card-head"><div><h2>'+title+'</h2>'+(subtitle?'<p>'+subtitle+'</p>':'')+'</div>'+action+'</div>'+body+'</section>';
const table = (headers, rows) => '<div class="table-wrap"><table><thead><tr>'+headers.map((h)=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.join(''):'<tr><td colspan="'+headers.length+'">'+empty('Nothing to show yet.')+'</td></tr>')+'</tbody></table></div>';
const page = (group, title, lede, body, actions='') => '<div class="page"><div class="page-head"><div><div class="eyebrow">'+group+'</div><h1>'+title+'</h1><p class="lede">'+lede+'</p></div><div class="actions">'+actions+'</div></div>'+body+'</div>';
const widePage = (group, title, lede, body, actions='') => page(group,title,lede,body,actions).replace('<div class="page">','<div class="page page-wide">');

async function loadWorkspaces() { const result=await api('/api/v1/workspaces'); state.workspaces=result.workspaces||[]; if(!state.selected || !state.workspaces.some((item)=>item.id===state.selected)) state.selected=state.workspaces[0]?.id||null; $('workspace-select').innerHTML='<option value="">'+t('Select workspace')+'</option>'+state.workspaces.map((item)=>'<option value="'+esc(item.id)+'">'+esc(item.name)+'</option>').join('')+'<option value="__new__">＋ '+t('New workspace')+'</option>'; $('workspace-select').value=state.selected||''; state.detail=state.selected?await api('/api/v1/workspaces/'+encodeURIComponent(state.selected)):null; }
async function loadRegistry() { const [capabilities,tools,agents,runtimes,skills,knowledge,events,audit,approvals]=await Promise.all([api('/api/v1/capabilities'),api('/api/v1/tools'),api('/api/v1/agents'),api('/api/v1/runtimes'),api('/api/v1/skills'),api('/api/v1/knowledge'),api('/api/v1/events'),api('/api/v1/audit'),api('/api/v1/approvals')]); state.registry={capabilities:capabilities.capabilities||[],tools:tools.tools||[],agents:agents.agents||[],runtimes:runtimes.runtimes||[],skills:skills.skills||[],knowledge:knowledge.knowledge||[],events:events.events||[],audit:audit.audit||[],approvals:approvals.approvals||[]}; }
function recordPage(pageName) { if(state.history[state.historyIndex]===pageName) return; state.history=state.history.slice(0,state.historyIndex+1); state.history.push(pageName); state.historyIndex=state.history.length-1; }
const pageLabels={overview:'Conversation management',tasks:'Task management',devices:'Device management',agents:'Agent management',validation:'Analysis and validation',connections:'Peripheral connections','peripheral-config':'Peripheral configuration',protocols:'Protocol analysis',vulnerabilities:'Vulnerability list','vuln-knowledge':'Vulnerability knowledge',runtime:'Runtime',skills:'Skills',capabilities:'Capability center',settings:'Settings'};
function renderTabs() { const tabs=$('tabs'); if(tabs) tabs.innerHTML='<div class="tab active"><span>'+esc(t(pageLabels[state.page]||state.page))+'</span></div>'; $('back').disabled=state.historyIndex<=0; $('forward').disabled=state.historyIndex>=state.history.length-1; localize(); }
function setPage(pageName, push=true) { if(push) recordPage(pageName); state.page=pageName; document.querySelectorAll('[data-page]').forEach((button)=>button.classList.toggle('active',button.dataset.page===pageName)); renderTabs(); renderPage(); }

function legacyOverview() { const targets=d().targets||[],tasks=d().tasks||[],findings=d().findings||[]; const metrics='<div class="grid cols-4"><div class="card metric"><div class="eyebrow">Workspaces</div><div class="metric-value">'+state.workspaces.length+'</div><div class="metric-note">research projects</div></div><div class="card metric"><div class="eyebrow">Targets</div><div class="metric-value">'+targets.length+'</div><div class="metric-note">selected workspace</div></div><div class="card metric"><div class="eyebrow">Tasks</div><div class="metric-value">'+tasks.length+'</div><div class="metric-note">scheduled runs</div></div><div class="card metric"><div class="eyebrow">Findings</div><div class="metric-value">'+findings.length+'</div><div class="metric-note">tracked hypotheses</div></div></div>'; const recent=tasks.slice().reverse().slice(0,5).map((item)=>'<div class="list-row"><div class="list-main"><strong>'+esc(item.type)+'</strong><p>'+esc(item.objective||item.id)+'</p></div>'+pill(item.status)+'</div>'); const findingRows=findings.slice().reverse().slice(0,5).map((item)=>'<div class="list-row"><div class="list-main"><strong>'+esc(item.title)+'</strong><p>'+esc(item.finding_id||item.id)+'</p></div>'+pill(item.state)+'</div>'); return page('Control plane','Research overview','Coordinate targets, capabilities, evidence, and findings from the local desktop console.',metrics+'<div class="split" style="margin-top:15px">'+card('Recent tasks','Latest execution state','<div>'+(recent.length?recent.join(''):empty('Select a workspace or submit a plan.'))+'</div>','<button class="btn" data-page-link="tasks">View all</button>')+card('Findings','Review and gate research results','<div>'+(findingRows.length?findingRows.join(''):empty('No findings in this workspace.'))+'</div>','<button class="btn" data-page-link="findings">Open findings</button>')+'</div>','<button class="btn primary" data-page-link="workspaces">New workspace</button>'); }
function workspaces() { const rows=state.workspaces.map((item)=>'<tr><td><strong>'+esc(item.name)+'</strong><div class="mono">'+esc(item.id)+'</div></td><td>'+esc(item.owner||'local')+'</td><td>'+esc(item.description||'-')+'</td><td>'+fmt(item.created_at)+'</td><td><button class="btn" data-open-workspace="'+esc(item.id)+'">Open</button></td></tr>'); const body='<div class="split">'+card('Workspace registry','Projects and authorization boundaries',table(['Name','Owner','Description','Created',''],rows))+card('Create workspace','Start a new research project','<div class="card-body"><form id="workspace-form" class="form"><div class="field"><label>Name</label><input name="name" required placeholder="router-research"></div><div class="field"><label>Owner</label><input name="owner" value="local"></div><div class="field"><label>Description</label><textarea name="description" placeholder="Authorized lab project"></textarea></div><div class="form-actions"><button class="btn primary">Create workspace</button></div></form></div>')+'</div>'; return page('Workspace','Workspaces','Keep every target, task, finding, and approval inside an explicit project.',body); }
function targets() { const items=d().targets||[]; const rows=items.map((item)=>'<tr><td><strong>'+esc(item.name)+'</strong><div class="mono">'+esc(item.id)+'</div></td><td>'+esc((item.vendor||'-')+' '+(item.model||''))+'</td><td>'+esc(item.address||'-')+'</td><td>'+esc(item.transport||'-')+'</td><td>'+(item.authorized?'<span class="pill">authorized</span>':'<span class="pill danger">unverified</span>')+'</td></tr>'); const body=card('Declared IoT targets',workspace()?'Targets in '+esc(workspace().name):'Select a workspace first',table(['Name','Vendor / model','Address','Transport','Authorization'],rows)); const form=workspace()?'<div style="margin-top:15px">'+card('Add IoT target','Declare a device, gateway, firmware endpoint, or lab asset before scheduling research','<div class="card-body"><form id="target-form" class="form"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required placeholder="lab-router"></div><div class="field"><label>Vendor</label><input name="vendor"></div><div class="field"><label>Model</label><input name="model"></div><div class="field"><label>Transport</label><input name="transport" placeholder="http / mqtt / serial"></div><div class="field full"><label>Address or identifier</label><input name="address" placeholder="192.0.2.10 or serial number"></div></div><div class="form-actions"><button class="btn primary">Add IoT target</button></div></form></div>')+'</div>':empty('Select a workspace from the left panel before adding an IoT target.'); return page('Workbench','Target management','Declare the IoT devices and assets that this workspace is authorized to inspect.',body+form); }
function tasks() { const items=(d().tasks||[]).slice().reverse(); const rows=items.map((item)=>{ const controls=[]; if(['queued','running','paused'].includes(item.status)) controls.push('<button class="btn" data-task-action="'+(item.status==='paused'?'resume':'pause')+'" data-id="'+esc(item.id)+'">'+(item.status==='paused'?'Resume':'Pause')+'</button>'); if(['failed','blocked','cancelled'].includes(item.status)) controls.push('<button class="btn" data-task-action="retry" data-id="'+esc(item.id)+'">Retry</button>'); if(!['completed','cancelled'].includes(item.status)) controls.push('<button class="btn" data-task-action="cancel" data-id="'+esc(item.id)+'">Cancel</button>'); return '<tr><td><strong>'+esc(item.type)+'</strong><div class="mono">'+esc(item.id)+'</div></td><td>'+pill(item.status)+'</td><td>'+esc(item.objective||'-')+'</td><td>'+fmt(item.created_at)+'</td><td><div class="actions">'+(controls.join('')||'-')+'</div></td></tr>'; }); return page('Research','Tasks','Track commander plans and capability runs for the selected workspace.',card('Task queue','Pause, resume, retry, or cancel scheduled work',table(['Task','Status','Objective','Created',''],rows)),workspace()?'<button class="btn primary" data-run-plan>Run passive plan</button>':'<span class="pill warn">Select workspace</span>'); }
function findings() { const items=(d().findings||[]).slice().reverse(); const rows=items.map((item)=>'<tr><td><strong>'+esc(item.title)+'</strong><div class="mono">'+esc(item.finding_id||item.id)+'</div></td><td>'+pill(item.state)+'</td><td>'+esc(item.priority||'-')+'</td><td>'+Math.round((item.confidence||0)*100)+'%</td><td>'+esc(item.evidence_ids?.length||0)+'</td><td><div class="actions"><button class="btn" data-gate="'+esc(item.finding_id||item.id)+'">Run gate</button><button class="btn" data-validate="'+esc(item.finding_id||item.id)+'">Validate</button></div></td></tr>'); return page('Research','Findings','Review hypotheses, apply the finding gate, and move validated results toward reporting.',card('Finding register',workspace()?'Findings in '+esc(workspace().name):'Select a workspace first',table(['Finding','State','Priority','Confidence','Evidence',''],rows))); }
