  const targetOptions=(d().targets||[]).map((item)=>'<option value="'+esc(item.id)+'">'+esc(item.name||item.model||item.id)+'</option>').join('');
  const capabilityOptions=(state.registry.capabilities||[]).map((item)=>'<option value="'+esc(item.id)+'">'+esc(item.id)+' · '+esc(item.category||'')+'</option>').join('');
  const createForm='<form id="task-form" class="form"><div class="field"><label>'+t('Select target')+'</label><select name="target_id" required>'+targetOptions+'</select></div><div class="field"><label>'+t('Capability')+'</label><select name="capability_id" required>'+capabilityOptions+'</select></div><div class="field"><label>'+t('Objective')+'</label><textarea name="objective" required placeholder="'+t('Objective')+'"></textarea></div><div class="form-actions"><button class="btn primary">'+t('Run task')+'</button></div></form>';
