    const nodes=(selected.nodes||[]).map((node)=>'<div class="task-node"><div class="task-node-head"><strong>'+esc(node.name)+'</strong>'+pill(node.status)+'</div><p>'+esc(node.summary||'-')+'</p>'+(node.output?'<pre>'+esc(JSON.stringify(node.output,null,2))+'</pre>':'')+'</div>').join('');
    const eventRows=(d().events||[]).filter((event)=>event.task_id===selected.id).slice().reverse().map((event)=>'<div class="event-row"><span class="mono">'+fmt(event.created_at)+'</span><strong>'+esc(event.type)+'</strong><span>'+esc(event.payload?.summary||event.payload?.to||'')+'</span></div>').join('');
