const views={overview,workspaces,targets,tasks,findings,evidence,files,capabilities,tools,agents,runtimes,runtime,models,devices,connections,'peripheral-config':peripheralConfig,protocols,skills,validation,knowledge,vulnerabilities,'vuln-knowledge':vulnKnowledge,risk,vendors,signatures,settings,approvals,events,audit};
async function createWorkspaceFromPicker() {
  const name=window.prompt(t('Workspace name'), 'iot-research');
  if(!name || !name.trim()) return;
  const description=window.prompt(t('Description'), t('IoT research workspace')) || '';
  try { const created=await api('/api/v1/workspaces',{method:'POST',body:JSON.stringify({name:name.trim(),owner:'local',description})}); state.selected=created.id; await renderPage(); toast(t('Workspace created')); } catch(error) { toast(error.message,true); }
}

function renderQueue() {
  const tasks=(d().tasks||[]).slice().reverse().filter((item)=>!state.search || JSON.stringify(item).toLowerCase().includes(state.search));
  const findings=(d().findings||[]).slice().reverse().filter((item)=>!state.search || JSON.stringify(item).toLowerCase().includes(state.search));
  const workspaces=state.workspaces.filter((item)=>!state.search || JSON.stringify(item).toLowerCase().includes(state.search));
  const taskRows=tasks.slice(0,12).map((item)=>'<div class="queue-row '+(state.page==='tasks'?'selected':'')+'" data-page="tasks"><span class="queue-icon">&#9654;</span><div class="queue-main"><strong>'+esc(item.objective||item.type)+'</strong><p>'+esc(item.type)+'</p></div><span class="queue-time">'+fmt(item.created_at)+'</span></div>');
  const findingRows=findings.slice(0,8).map((item)=>'<div class="queue-row '+(state.page==='findings'?'selected':'')+'" data-page="findings"><span class="queue-icon">!</span><div class="queue-main"><strong>'+esc(item.title)+'</strong><p>'+esc(item.priority||'finding')+'</p></div><span class="queue-time">'+fmt(item.created_at)+'</span></div>');
  const workspaceRows=workspaces.slice(0,5).map((item)=>'<div class="queue-row '+(state.selected===item.id?'selected':'')+'" data-open-workspace="'+esc(item.id)+'"><span class="queue-icon">&#9632;</span><div class="queue-main"><strong>'+esc(item.name)+'</strong><p>'+esc(item.owner||'local')+'</p></div><span class="queue-time">'+fmt(item.created_at)+'</span></div>');
  $('queue').innerHTML='<div class="queue-head"><strong class="queue-title">'+t('Chat and tasks')+'</strong><button class="queue-action" data-page="devices">+</button></div><div class="queue-tabs"><button class="active">'+t('All')+'</button><button>'+t('Running')+'</button><button>'+t('Completed')+'</button></div><div class="queue-section">'+t('Workspaces')+'</div>'+(workspaceRows.join('')||empty(t('Nothing to show yet.')))+'<div class="queue-section">'+t('Tasks')+'</div>'+(taskRows.join('')||empty(t('Nothing to show yet.')))+'<div class="queue-section">'+t('Vulnerability list')+'</div>'+(findingRows.join('')||empty(t('Nothing to show yet.')));
}
