function applyLayout() {
  const queuePages=['tasks'];
  const inspectorPages=['tasks','devices','connections','validation','vulnerabilities'];
  const workbench=document.querySelector('.workbench');
  const hasQueue=queuePages.includes(state.page), hasInspector=inspectorPages.includes(state.page);
  const mode=hasQueue && hasInspector ? 'layout-queue-content-inspector' : hasQueue ? 'layout-queue-content' : hasInspector ? 'layout-content-inspector' : 'layout-content';
  workbench.className='workbench '+mode;
}
let liveTimer=null;
let taskStream=null;
let taskStreamID=null;
function closeTaskStream() { if(taskStream){ taskStream.close(); taskStream=null; taskStreamID=null; } }
function ensureTaskStream() {
  const selected=state.page==='tasks' && state.taskSelected;
  if(!selected){ closeTaskStream(); return; }
  if(taskStream && taskStreamID===selected) return;
  closeTaskStream();
  taskStreamID=selected;
  taskStream=new EventSource(API+'/api/v1/tasks/'+encodeURIComponent(selected)+'/events');
  taskStream.onmessage=async()=>{ try { await loadWorkspaces(); if(state.page==='tasks'){ $('content').innerHTML=(views.tasks||taskManagement)(); renderQueue(); renderInspector(); localize(); } } catch(error) { toast(error.message,true); } };
  taskStream.onerror=()=>{ if(taskStream && taskStream.readyState===EventSource.CLOSED) closeTaskStream(); };
}
function ensureLiveRefresh() {
  const live=['overview','tasks'].includes(state.page);
  if(!live && liveTimer){ clearInterval(liveTimer); liveTimer=null; }
  if(!live){ closeTaskStream(); }
  if(live && !liveTimer){ liveTimer=setInterval(async()=>{ try { await loadWorkspaces(); if(!['overview','tasks'].includes(state.page)){clearInterval(liveTimer);liveTimer=null;return;} if(state.page==='tasks' && taskStream) return; $('content').innerHTML=(views[state.page]||overview)(); renderQueue(); renderInspector(); localize(); ensureTaskStream(); } catch(error) { toast(error.message,true); } },1500); }
  ensureTaskStream();
}
async function renderPage() { applyLayout(); $('content').innerHTML='<div class="loading">'+t('Loading IoTHunter...')+'</div>'; try { await loadWorkspaces(); if(['overview','tasks','capabilities','tools','agents','runtimes','runtime','models','skills','knowledge','vuln-knowledge','vendors','signatures','protocols','approvals','events','audit'].includes(state.page)) await loadRegistry(); $('content').innerHTML=(views[state.page]||overview)(); renderQueue(); renderInspector(); localize(); ensureLiveRefresh(); } catch(error) { $('content').innerHTML=page('Error','IoTHunter is offline',error.message,empty('Start the local control plane and refresh the client.')); $('connection').textContent=t('Connection error'); document.querySelector('.online-dot').classList.add('offline'); renderQueue(); renderInspector(); localize(); toast(error.message,true); } }

async function submitForm(event) { event.preventDefault(); const form=event.target; const value=Object.fromEntries(new FormData(form).entries()); try { if(form.id==='workspace-form'){ const created=await api('/api/v1/workspaces',{method:'POST',body:JSON.stringify(value)}); state.selected=created.id; toast('Workspace created'); await loadWorkspaces(); setPage('overview'); } else if(form.id==='target-form'){ if(!state.selected) throw new Error('Select a workspace first'); value.authorized=true; await api('/api/v1/workspaces/'+state.selected+'/targets',{method:'POST',body:JSON.stringify(value)}); toast('Target added'); await renderPage(); } else if(form.id==='device-form'){ value.authorized=true; await api('/api/v1/workspaces/'+state.selected+'/devices',{method:'POST',body:JSON.stringify(value)}); toast('Device declared'); await renderPage(); } else if(form.id==='device-config-form'){ if(!state.selected || !state.deviceSelected) throw new Error('Select a device first'); const config={voltage_limit:value.voltage_limit,current_limit:value.current_limit,destructive:Boolean(value.destructive)}; await api('/api/v1/workspaces/'+encodeURIComponent(state.selected)+'/devices/'+encodeURIComponent(state.deviceSelected),{method:'POST',body:JSON.stringify({status:value.status,transport:value.transport,serial:value.serial,config})}); toast('Device configuration applied'); await renderPage(); } else if(form.id==='knowledge-form'){ const content=value.content.trim()?JSON.parse(value.content):{}; await api('/api/v1/knowledge',{method:'POST',body:JSON.stringify({kind:value.kind,title:value.title,content})}); toast('Knowledge saved'); await loadRegistry(); await renderPage(); } else if(form.id==='evidence-form'){ const content=value.content.trim()?JSON.parse(value.content):{}; await api('/api/v1/findings/'+encodeURIComponent(value.finding_id)+'/evidence',{method:'POST',body:JSON.stringify({type:value.type,content,confidence:1})}); toast('Evidence added'); await renderPage(); } } catch(error) { toast(error.message,true); } }

document.addEventListener('click', async (event) => { const nav=event.target.closest('[data-page]'); if(nav){setPage(nav.dataset.page);return;} const link=event.target.closest('[data-page-link]'); if(link){setPage(link.dataset.pageLink);return;} if(event.target.closest('#settings-language')){$('language').click();return;} const open=event.target.closest('[data-open-workspace]'); if(open){state.selected=open.dataset.openWorkspace; $('workspace-select').value=state.selected; setPage('overview');return;} const agentSelect=event.target.closest('[data-agent-select]'); if(agentSelect){state.agentSelected=agentSelect.dataset.agentSelect;await renderPage();return;} const deviceSelect=event.target.closest('[data-device-select]'); if(deviceSelect){state.deviceSelected=deviceSelect.dataset.deviceSelect;await renderPage();return;} const deviceDisconnect=event.target.closest('[data-device-disconnect]'); if(deviceDisconnect){try{await api('/api/v1/workspaces/'+encodeURIComponent(state.selected)+'/devices/'+encodeURIComponent(deviceDisconnect.dataset.deviceDisconnect),{method:'POST',body:JSON.stringify({status:'offline'})});toast('Peripheral disconnected');await renderPage();}catch(e){toast(e.message,true);}return;} const agentStop=event.target.closest('[data-agent-stop]'); if(agentStop){try{await api('/api/v1/agents/'+encodeURIComponent(agentStop.dataset.agentStop),{method:'POST',body:JSON.stringify({enabled:false})});toast('Agent stopped');await loadRegistry();await renderPage();}catch(e){toast(e.message,true);}return;} const runtimeCheck=event.target.closest('[data-runtime-check]'); if(runtimeCheck){try{await api('/api/v1/runtimes/'+encodeURIComponent(runtimeCheck.dataset.runtimeCheck)+'/check',{method:'POST',body:'{}'});toast('Runtime checked');await loadRegistry();await renderPage();}catch(e){toast(e.message,true);}return;} const runtimeProbe=event.target.closest('[data-runtime-probe]'); if(runtimeProbe){try{const result=await api('/api/v1/runtimes/'+encodeURIComponent(runtimeProbe.dataset.runtimeProbe)+'/probe',{method:'POST',body:'{}'});window.alert(result.output||'No help output returned');}catch(e){toast(e.message,true);}return;} const runtimeUnbind=event.target.closest('[data-runtime-unbind]'); if(runtimeUnbind){try{await api('/api/v1/agents/'+encodeURIComponent(runtimeUnbind.dataset.runtimeUnbind),{method:'POST',body:JSON.stringify({runtime_id:''})});toast('Runtime unbound');await loadRegistry();await renderPage();}catch(e){toast(e.message,true);}return;} const gate=event.target.closest('[data-gate]'); if(gate){try{await api('/api/v1/findings/'+encodeURIComponent(gate.dataset.gate)+'/gate',{method:'POST',body:JSON.stringify({gate:'finding'})});toast('Finding gate completed');await renderPage();}catch(e){toast(e.message,true);}return;} const validate=event.target.closest('[data-validate]'); if(validate){const method=window.prompt(state.lang==='zh'?'验证方法':'Validation method','manual.review');if(!method)return;try{await api('/api/v1/findings/'+encodeURIComponent(validate.dataset.validate)+'/validate',{method:'POST',body:JSON.stringify({method,reproducible:true,result:state.lang==='zh'?'人工验证完成':'Manual validation completed',impact:'documented'})});toast(state.lang==='zh'?'发现已验证':'Finding validated');await renderPage();}catch(e){toast(e.message,true);}return;} const approve=event.target.closest('[data-approve]'); if(approve){try{await api('/api/v1/approvals/'+encodeURIComponent(approve.dataset.approve),{method:'POST',body:JSON.stringify({status:'approved',actor:'desktop-ui'})});toast('Approval granted');await loadRegistry();await renderPage();}catch(e){toast(e.message,true);}return;} const task=event.target.closest('[data-task-action]'); if(task){try{await api('/api/v1/tasks/'+encodeURIComponent(task.dataset.id)+'/'+task.dataset.taskAction,{method:'POST',body:'{}'});toast('Task updated');await renderPage();}catch(e){toast(e.message,true);}return;} const cap=event.target.closest('[data-test-cap]'); if(cap){try{await api('/api/v1/capabilities/'+encodeURIComponent(cap.dataset.testCap)+'/test',{method:'POST',body:JSON.stringify({objective:'Manual capability test',inputs:{}})});toast('Capability test submitted');}catch(e){toast(e.message,true);}return;} if(event.target.closest('[data-run-plan]')){if(!state.selected)return toast('Select a workspace first',true);if(!d().targets?.length)return toast('Add a target before running research',true);try{await api('/api/v1/workspaces/'+state.selected+'/plan',{method:'POST',body:JSON.stringify({target_id:d().targets[0].id,objective:'Run passive reconnaissance and apply the finding gate',capabilities:['target.fingerprint']})});toast('Commander plan submitted');setTimeout(renderPage,180);}catch(e){toast(e.message,true);}} });
document.addEventListener('change', async (event) => { const binding=event.target.closest('[data-agent-runtime]'); if(!binding || !binding.value)return; try { await api('/api/v1/agents/'+encodeURIComponent(binding.dataset.agentRuntime),{method:'POST',body:JSON.stringify({runtime_id:binding.value})}); toast('Runtime bound'); await loadRegistry(); await renderPage(); } catch(error) { toast(error.message,true); } });
document.addEventListener('submit', submitForm);
document.addEventListener('submit', async (event) => {
  const form=event.target; if(!['conversation-form','peripheral-form','peripheral-config-form','task-form'].includes(form.id)) return;
  event.preventDefault(); const value=Object.fromEntries(new FormData(form).entries());
  try {
    if(form.id==='conversation-form') {
      if(!state.selected) throw new Error(t('Select workspace'));
      const selected=state.detail?.conversations?.find((item)=>item.id===state.conversationSelected);
      let conversationID=selected?.id;
      if(!conversationID) { const created=await api('/api/v1/workspaces/'+encodeURIComponent(state.selected)+'/conversations',{method:'POST',body:JSON.stringify({title:value.content.slice(0,42)})}); conversationID=created.id; state.conversationSelected=conversationID; }
      await api('/api/v1/conversations/'+encodeURIComponent(conversationID)+'/message',{method:'POST',body:JSON.stringify({content:value.content,create_task:Boolean(value.create_task),target_id:value.target_id||''})});
      await renderPage(); return;
    }
    if(form.id==='peripheral-form') {
      if(!state.selected) throw new Error(t('Select workspace'));
      const created=await api('/api/v1/workspaces/'+encodeURIComponent(state.selected)+'/peripherals',{method:'POST',body:JSON.stringify({name:value.name,kind:value.kind,driver:value.driver,port:value.port,capabilities:[]})});
      if(value.target_id) await api('/api/v1/workspaces/'+encodeURIComponent(state.selected)+'/attachments',{method:'POST',body:JSON.stringify({target_device_id:value.target_id,peripheral_id:created.id,role:value.role||'debug'})});
      toast(t('Discover peripherals')); await renderPage(); return;
    }
    if(form.id==='peripheral-config-form') {
      if(!state.deviceSelected) throw new Error(t('Declare a peripheral'));
      let config={}; let safety_limits={}; try { config=value.config?.trim()?JSON.parse(value.config):{}; safety_limits=value.safety_limits?.trim()?JSON.parse(value.safety_limits):{}; } catch { throw new Error('Config must be valid JSON'); }
      await api('/api/v1/peripherals/'+encodeURIComponent(state.deviceSelected),{method:'POST',body:JSON.stringify({config,safety_limits})}); toast(t('Apply configuration')); await renderPage();
    }
    if(form.id==='task-form') {
      if(!state.selected) throw new Error(t('Select workspace'));
      await api('/api/v1/workspaces/'+encodeURIComponent(state.selected)+'/plan',{method:'POST',body:JSON.stringify({target_id:value.target_id,objective:value.objective,capabilities:[value.capability_id],permissions:{filesystem:'workspace-readonly'},budget:{max_runtime_seconds:300,max_tool_calls:10}})});
      toast(t('Task created')); state.taskSelected=null; await renderPage();
    }
  } catch(error) { toast(error.message,true); }
});
document.addEventListener('click', async (event) => {
  const create=event.target.closest('[data-new-conversation]');
  if(create) { if(!state.selected) return toast(t('Select workspace'),true); try { const result=await api('/api/v1/workspaces/'+encodeURIComponent(state.selected)+'/conversations',{method:'POST',body:JSON.stringify({title:t('New conversation')})}); state.conversationSelected=result.id; await renderPage(); } catch(error) { toast(error.message,true); } return; }
  const select=event.target.closest('[data-conversation-select]'); if(select) { state.conversationSelected=select.dataset.conversationSelect; renderPage(); return; }
  const taskSelect=event.target.closest('[data-task-select]'); if(taskSelect) { state.taskSelected=taskSelect.dataset.taskSelect; renderPage(); return; }
  const peripheral=event.target.closest('[data-peripheral-status]'); if(peripheral) { try { await api('/api/v1/peripherals/'+encodeURIComponent(peripheral.dataset.peripheralId),{method:'POST',body:JSON.stringify({status:peripheral.dataset.peripheralStatus,occupied_by:peripheral.dataset.peripheralStatus==='connected'?'desktop-ui':''})}); await renderPage(); } catch(error) { toast(error.message,true); } }
});
$('workspace-select').addEventListener('change', async (event)=>{if(event.target.value==='__new__'){event.target.value=state.selected||'';await createWorkspaceFromPicker();return;}state.selected=event.target.value||null;state.conversationSelected=null;state.taskSelected=null;await renderPage();});
$('language').addEventListener('click', async ()=>{state.lang=state.lang==='zh'?'en':'zh';localStorage.setItem('iothunter.lang',state.lang);renderTabs();await renderPage();});
$('settings').addEventListener('click', ()=>toast(state.lang==='zh'?'设置页面将在下一版本开放':'Settings page is coming soon'));
$('global-search').addEventListener('input', (event)=>{state.search=event.target.value.trim().toLowerCase();renderQueue();});
$('refresh').addEventListener('click', async ()=>{try{await loadWorkspaces();await loadRegistry();await renderPage();toast('Data refreshed');}catch(e){toast(e.message,true);}});
$('back').addEventListener('click',()=>{if(state.historyIndex>0){state.historyIndex--;state.page=state.history[state.historyIndex];renderTabs();renderPage();}});
$('forward').addEventListener('click',()=>{if(state.historyIndex<state.history.length-1){state.historyIndex++;state.page=state.history[state.historyIndex];renderTabs();renderPage();}});

(async()=>{try{localize();await loadWorkspaces();await loadRegistry();recordPage(state.page);renderTabs();await renderPage();}catch(error){applyLayout();$('connection').textContent='Start sidecar';document.querySelector('.online-dot').classList.add('offline');$('content').innerHTML=page('Error','IoTHunter is offline',error.message,empty('The local control plane could not be reached.'));localize();}})();
